const upright = (x, y, w, h, lean = 0, notch = 0.19) => [
  [x + w * 0.09, y + 3], [x + w * 0.26, y],
  [x + w * 0.64, y - 1], [x + w * 0.88, y + 3],
  [x + w * 0.94 + lean * 0.45, y + h * 0.48],
  [x + w + lean, y + h],
  [x + w * 0.76 + lean, y + h * (1 - notch * 0.75)],
  [x + w * 0.52 + lean, y + h * (1 - notch)],
  [x + w * 0.28 + lean, y + h * (1 - notch * 0.78)],
  [x + lean, y + h],
  [x + w * 0.04 + lean * 0.45, y + h * 0.46],
];

